function goldDraw(c){
  var S=G.flow&&G.flow.gold, e, s, q, z, t=G.t||0, pu, gr, R, k, a, cy;
  if(!S||!S.ref||S.dead) return;
  e=S.ref; if(!(e.hp>0)) return;
  q=ZOOM(); z=Math.max(1,hudRes()); s=w2s(e.x,0,e.y); R=e.r*q;
  if(s.x<-R*4||s.y<-R*4||s.x>W+R*4||s.y>H+R*4) return;
  pu=0.55+0.45*Math.sin(t*3.4+e.x*0.02);
  c.save(); c.globalCompositeOperation='lighter';
  gr=c.createRadialGradient(s.x,s.y,0,s.x,s.y,R*2.6);
  gr.addColorStop(0,'rgba(255,199,46,'+(0.30*pu).toFixed(3)+')'); gr.addColorStop(1,'rgba(255,170,30,0)');
  c.fillStyle=gr; c.beginPath(); c.arc(s.x,s.y,R*2.6,0,6.2832); c.fill();
  c.strokeStyle='rgba(255,210,80,'+(0.45+0.35*pu).toFixed(3)+')'; c.lineWidth=2.5*z;
  c.beginPath(); c.ellipse(s.x,s.y+2*z,R*1.35,Math.max(3*z,R*0.55),0,0,6.2832); c.stroke();
  cy=s.y-R*1.1; c.fillStyle='rgba(255,240,180,.9)';
  for(k=0;k<3;k++){ a=t*2.2+k*2.094; c.fillRect(s.x+Math.cos(a)*R*1.3-1.2*z,cy+Math.sin(a)*R*0.9-1.2*z,2.4*z,2.4*z); }
  c.restore();
  c.save(); c.textAlign='center'; c.font=hudFS(TYPE.micro); c.fillStyle='#ffd24a'; hudText('GOLDEN',s.x,s.y-R*1.9-LH(6)*z); c.restore();
}

edits.replacement:
// v16.xx (goldlook), HIS STANDING ORDER (2026-10-14): new features polished to the level of the rest of the game, and the cloud review (finding 6): the golden enemy was lit and named through walls and the fog, and its body
// looked like any other. It is GOLD now: the body wears the elite outline in gold (a crisp inner line, a soft outer one, a faint tint, the same code as the elites), under it a soft gold glow, a ring on the ground and sparkles
// drawn in the world (so a wall in front of it covers them), and all of it, the name too, only where its body is SEEN (the same sight and fog rule as the body itself, a teammate's sight counts). It was a floating HUD
// label over empty ground when it stood behind a wall.
function goldAura(e){
  var t=G.t||0, r=e.r, x=e.x, y=e.y, pu=0.55+0.45*Math.sin(t*3.4+x*0.02), gr, k, a, tw, sx, sy, u;
  if(!(e.hp>0)||!(r>0)) return;
  wc.save(); wc.globalCompositeOperation='lighter';
  gr=wc.createRadialGradient(x,y,r*0.4,x,y,r*2.8);
  gr.addColorStop(0,'rgba(255,199,46,'+(0.34*pu).toFixed(3)+')'); gr.addColorStop(1,'rgba(255,170,30,0)');
  wc.fillStyle=gr; wc.beginPath(); wc.ellipse(x,y+2,r*2.8,r*1.5,0,0,6.2832); wc.fill();
  wc.strokeStyle='rgba(255,214,90,'+(0.40+0.30*pu).toFixed(3)+')'; wc.lineWidth=1.6; wc.beginPath(); wc.ellipse(x,y+2,r*1.45,r*0.72,0,0,6.2832); wc.stroke();
  for(k=0;k<6;k++){
    a=t*1.5+k*1.0472; tw=0.5+0.5*Math.sin(t*6+k*2.1); u=2+2.2*tw;
    sx=x+Math.cos(a)*r*1.25; sy=y-r*0.9+Math.sin(a)*r*0.7-5*tw;
    wc.fillStyle='rgba(255,244,190,'+(0.35+0.6*tw).toFixed(3)+')';
    wc.fillRect(sx-u,sy-0.6,u*2,1.2); wc.fillRect(sx-0.6,sy-u,1.2,u*2);
  }
  wc.restore();
}
function goldDrPush(DR,ox,oy,VW,VH){
  var S=G.flow&&G.flow.gold, e;
  if(!S||!S.ref||S.dead) return;
  e=S.ref; if(!(e.hp>0)||!e.seen) return;
  if(e.x<ox-220||e.x>ox+VW+220||e.y<oy-220||e.y>oy+VH+220) return;
  if(e.name&&String(e.name).indexOf('GOLDEN ')!==0) e.name='GOLDEN '+e.name;   // the nameplate says so, in the same plate as every name
  DR.push({k:e.y-1,fn:goldAura.bind(null,e)});
}
